/* Original six-step violin journey. No media/permission request is performed by this module. */
(function(root,factory){'use strict';const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;else root.SVLearningJourney=api;})(typeof globalThis==='object'?globalThis:this,function(root){
  'use strict';
  const VERSION=1,STORAGE_KEY='smartvio-learning-journey-v1',LANGUAGES=['zh','en','ja','de'],PHASES=['watch','try','review'];
  const L=(zh,en,ja,de)=>({zh,en,ja,de}),clone=value=>JSON.parse(JSON.stringify(value));
  const STEPS=[
    {id:'prepare',title:L('选琴与准备','Choose and prepare','楽器と準備','Instrument und Vorbereitung'),goal:L('先准备好琴、琴弓和一小段安静的时间。','Prepare your violin, bow and a little quiet time.','楽器と弓、落ち着いて練習できる時間を用意します。','Lege Violine und Bogen bereit und nimm dir etwas ruhige Zeit.'),instructions:[L('确认正在使用电子或原声小提琴；可以保留你已经做过的选择。','Confirm electric or acoustic violin. Keep the choice you already made.','電子・アコースティックの選択を確認します。前の設定はそのまま使えます。','Prüfe die Auswahl elektrisch oder akustisch. Deine bisherige Auswahl bleibt bestehen.'),L('调好肩托与站姿，先熟悉按钮。基础学习无需登录或连接设备。','Set up your shoulder rest and stance, then explore the controls. Basic learning needs no account or connected device.','肩当てと立ち方を整え、操作を確認します。基本の学習はログインや機器接続なしで使えます。','Richte Schulterstütze und Stand ein und lerne die Bedienung kennen. Zum Einstieg sind weder Konto noch Geräteverbindung nötig.')],entry:{page:'profile'},entryLabel:L('确认我的乐器','Check my instrument','楽器の設定を確認','Instrument prüfen'),legacyReferences:{buttonGuide:['instrument'],curriculum:['prepare'],lesson:[]}},
    {id:'hold',title:L('持琴与持弓','Hold violin and bow','構え方と弓の持ち方','Violine und Bogen halten'),goal:L('先找到舒适、放松的姿势，再开始拉琴。','Find a comfortable, relaxed position before playing.','まず楽で力の抜けた構えを見つけます。','Finde vor dem Spielen eine bequeme, lockere Haltung.'),instructions:[L('肩膀放松，琴放稳。看图确认琴颈、琴桥与弓的位置。','Relax your shoulders and support the violin. Locate its neck, bridge and bow in the illustration.','肩の力を抜き、楽器を安定させます。図でネック・駒・弓の位置を確認します。','Lass die Schultern locker und halte die Violine stabil. Suche Hals, Steg und Bogen in der Illustration.'),L('手指自然弯曲，轻握琴弓。图示只提供参考，不会判断你的姿势是否正确。','Curve your fingers naturally and hold the bow gently. This illustration is a reference, not a posture assessment.','指を自然に曲げ、弓を軽く持ちます。図は参考であり、姿勢を判定するものではありません。','Krümme die Finger natürlich und halte den Bogen leicht. Die Illustration ist eine Hilfe, keine Haltungsbewertung.')],entry:{page:'practice',lessonId:'settle'},entryLabel:L('看持琴示范','Open posture guide','構え方の手本を見る','Haltungsbeispiel öffnen'),legacyReferences:{buttonGuide:[],curriculum:['prepare'],lesson:['settle'],oldCourse:['hold']}},
    {id:'tune',title:L('认弦与调音','Strings and tuning','弦を知り調弦する','Saiten und Stimmung'),goal:L('认识 G、D、A、E，先听参考音，再看调音器。','Learn G, D, A and E. Hear a reference, then use the tuner.','G・D・A・Eを覚え、基準音を聴いて調弦します。','Lerne G, D, A und E. Höre zuerst den Referenzton, dann nutze das Stimmgerät.'),instructions:[L('从低到高依次是 G、D、A、E；一次只听、只拉一根弦。','The strings run from low G through D and A to high E. Listen to and play one string at a time.','低い方からG・D・A・Eです。一度に1本ずつ聴いて弾きます。','Die Saiten heißen von tief nach hoch G, D, A und E. Höre und spiele jeweils nur eine Saite.'),L('打开调音器后主动点击开始，才会请求麦克风；也可以只听参考音。','Microphone access is requested only after you start tuning. You may simply listen to reference tones instead.','調弦開始を押したときだけマイクの許可を求めます。基準音を聴くだけでも使えます。','Der Mikrofonzugriff wird erst beim Start angefragt. Du kannst auch nur Referenztöne anhören.')],entry:{page:'tuner',target:'[data-action="start-tuner"]'},entryLabel:L('打开调音器','Open tuner','チューナーを開く','Stimmgerät öffnen'),legacyReferences:{buttonGuide:['tuner'],curriculum:['prepare'],lesson:[],oldCourse:['open']}},
    {id:'open',title:L('空弦与节奏','Open strings and rhythm','開放弦とリズム','Leere Saiten und Rhythmus'),goal:L('先数四拍，再用空弦拉出均匀的长音。','Count four beats, then play a steady open-string note.','4拍数えてから、開放弦で均一な長い音を出します。','Zähle vier Schläge und spiele dann einen gleichmäßigen Ton auf einer leeren Saite.'),instructions:[L('从 D 弦或 A 弦开始，用弓中段慢慢拉，不急着加速。','Start on D or A with the middle of the bow and a slow pace.','D線かA線から、弓の中ほどでゆっくり弾きます。','Beginne auf D oder A und spiele langsam in der Bogenmitte.'),L('先听示范，再跟着练。觉得忙乱时只保留琴谱或运弓提示。','Listen first, then follow. If it feels busy, focus on only the score or bow cue.','手本を聴いてから合わせます。難しいときは譜面か弓の表示の一つに集中します。','Höre zuerst zu und spiele dann mit. Konzentriere dich bei Bedarf nur auf Noten oder Bogenhinweis.')],entry:{page:'practice',lessonId:'open-strings'},entryLabel:L('练一段空弦','Practise open strings','開放弦を練習','Leere Saiten üben'),legacyReferences:{buttonGuide:['beat'],curriculum:['open-tone'],lesson:['open-strings'],oldCourse:['bow']}},
    {id:'fingers',title:L('左手指法','Left-hand fingers','左手の指使い','Finger der linken Hand'),goal:L('先比较空弦与 1 指，再逐步加入其他手指。','Compare an open string with finger 1, then gradually add the other fingers.','開放弦と1の指を比べてから、ほかの指を少しずつ加えます。','Vergleiche leere Saite und ersten Finger, bevor du weitere Finger ergänzt.'),instructions:[L('手指轻落在弦上，不捏紧琴颈；先听目标音，再慢慢试。','Place the finger lightly without gripping the neck. Hear the target note before trying it.','ネックを握り込まず、指を軽く置きます。目標の音を聴いてから試します。','Setze den Finger leicht auf und umklammere den Hals nicht. Höre zuerst den Zielton.'),L('看指板上的当前手指与弦名。单音提示只作参考，不是专业考试评分。','Read the active finger and string on the fingerboard. Single-note feedback is a reference, not an exam score.','指板の指番号と弦名を確認します。単音の表示は参考で、試験の点数ではありません。','Beachte Fingerzahl und Saite auf dem Griffbrett. Einzeltonhinweise sind eine Hilfe, keine Prüfungsnote.')],entry:{page:'practice',lessonId:'first-fingers'},entryLabel:L('慢练左手指法','Try the finger exercise','指使いをゆっくり練習','Fingerübung starten'),legacyReferences:{buttonGuide:[],curriculum:['fingers'],lesson:['first-fingers'],oldCourse:['finger']}},
    {id:'melody',title:L('第一首曲','Your first melody','初めての曲','Deine erste Melodie'),goal:L('把小片段连起来，拉出属于你的第一句旋律。','Join small phrases into your first melody.','短いフレーズをつなぎ、初めてのメロディーを弾きます。','Verbinde kurze Phrasen zu deiner ersten Melodie.'),instructions:[L('先听原创练习曲《晨光四弦》，再把难点用 A–B 循环慢练。','Hear the original exercise Four Strings at Dawn, then use A–B loops to practise its tricky parts slowly.','オリジナル練習曲「夜明けの四弦」を聴き、難しい部分をA–Bループでゆっくり練習します。','Höre die Originalübung Vier Saiten im Morgenlicht und übe schwierige Stellen langsam mit A–B-Schleifen.'),L('练好后可以录一小段回听。进度由你确认，不会自动判定演奏合格。','Record a short phrase to listen back if you wish. You confirm progress yourself; playing is not automatically graded.','短く録音して聴き直すこともできます。進み具合は自己確認で、演奏を自動採点しません。','Nimm bei Bedarf eine kurze Phrase zum Nachhören auf. Du bestätigst deinen Fortschritt selbst; es gibt keine automatische Leistungsnote.')],entry:{page:'practice',lessonId:'dawn-melody'},entryLabel:L('开始第一首曲','Play the first melody','初めての曲を練習','Erste Melodie starten'),legacyReferences:{buttonGuide:['phrase','record','next'],curriculum:['first-phrase'],lesson:['dawn-melody'],oldCourse:['phrase','record']}}
  ];
  const IDS=STEPS.map(s=>s.id),WORDS={
    title:L('一步一步，把小提琴拉响','One small step towards your music','一歩ずつ、バイオリンを奏でよう','Schritt für Schritt zu deiner Musik'),intro:L('只专注眼前这一步。原课程仍在下方课程库。','Focus on this step. Previous courses remain in the course library below.','今の一歩に集中しましょう。これまでの講座は下のライブラリにあります。','Konzentriere dich auf diesen Schritt. Bisherige Kurse bleiben in der Kursbibliothek darunter.'),
    step:L('第 {n} / 6 步','Step {n} of 6','6ステップ中 {n}','Schritt {n} von 6'),count:L('{n} / 6 步已回顾','{n} of 6 steps reviewed','6ステップ中 {n} を振り返り済み','{n} von 6 Schritten wiederholt'),watch:L('看示范','Watch','手本を見る','Ansehen'),try:L('试一试','Try','試してみる','Ausprobieren'),review:L('回听 / 复习','Review','聴き直す・復習','Nachhören / Wiederholen'),
    previous:L('上一步','Previous','前へ','Zurück'),skip:L('跳过这步','Skip this step','このステップをスキップ','Schritt überspringen'),pending:L('待练习','To practise','これから練習','Noch zu üben'),reviewed:L('已回顾','Reviewed','復習済み','Wiederholt'),skipped:L('已跳过 · 可回来','Skipped · revisit anytime','スキップ済み・いつでも戻れます','Übersprungen · jederzeit zurück'),current:L('当前步骤','Current step','現在のステップ','Aktueller Schritt'),
    watchNext:L('看过了，试一试','Ready to try','見たので、試してみる','Jetzt ausprobieren'),tryNext:L('我练过了，回顾一下','I practised — review','練習したので、振り返る','Geübt — jetzt wiederholen'),finish:L('我已回顾，下一步','Reviewed — next step','復習して、次へ','Wiederholt — weiter'),finished:L('我已回顾这一步','Mark this step reviewed','このステップを復習済みにする','Diesen Schritt als wiederholt markieren'),undo:L('撤销这步的回顾标记','Undo reviewed mark','復習済みを取り消す','Wiederholt-Markierung aufheben'),
    reflection:L('回想刚才的一次练习：哪一处更轻松，下一次想慢练哪里？可以随时返回示范。','Think about your last try: what felt easier, and what would you practise slowly next? Revisit the example anytime.','今の練習で楽になったところ、次にゆっくり試したいところを振り返ります。いつでも手本に戻れます。','Was fiel dir leichter? Was möchtest du als Nächstes langsam üben? Kehre jederzeit zum Beispiel zurück.'),
    record:L('录一段，回听','Record and listen back','録音して聴き直す','Aufnehmen und nachhören'),pause:L('暂停示范','Pause animation','動きを一時停止','Animation pausieren'),play:L('播放示范','Play animation','動きを再生','Animation abspielen'),replay:L('重播','Replay','もう一度','Erneut abspielen'),reduce:L('减少动态','Reduce motion','動きを減らす','Bewegung reduzieren'),
    illustration:L('无声动作示意 · 点“试一试”进入练习，不检测姿势','Silent motion guide · choose Try for practice, not posture assessment','無音の動作ガイド・練習は「試してみる」へ。姿勢判定ではありません','Stumme Bewegungshilfe · zum Üben „Ausprobieren“, keine Haltungsbewertung'),progressNote:L('“已回顾”由你自行确认，代表学习记录，不代表演奏考试通过。','You mark a step as reviewed. This is a learning record, not a passed playing test.','復習済みは自己確認の記録で、演奏試験の合格を示しません。','Du markierst Schritte selbst als wiederholt. Das ist ein Lernprotokoll, keine bestandene Spielprüfung.'),
    allDone:L('六步都已回顾。继续练喜欢的曲子，或打开下方课程库。','You reviewed all six steps. Keep practising a favourite piece or explore the courses below.','6ステップを振り返りました。好きな曲を続けるか、下の講座を開きましょう。','Du hast alle sechs Schritte wiederholt. Übe ein Lieblingsstück oder öffne die Kurse darunter.'),saved:L('进度已保存在此浏览器。','Progress saved in this browser.','進み具合をこのブラウザーに保存しました。','Fortschritt in diesem Browser gespeichert.'),volatile:L('当前无法保存进度；本页仍可继续，刷新可能丢失。','Progress cannot be saved right now. You can continue here, but a reload may lose changes.','現在は保存できません。このページでは続けられますが、再読込で変更が失われる場合があります。','Der Fortschritt kann gerade nicht gespeichert werden. Du kannst weiterüben, beim Neuladen könnten Änderungen verloren gehen.'),corrupt:L('旧的主线记录暂时无法读取，原数据未改动；你仍可继续练习。','The saved journey could not be read. Original data was preserved; you can keep practising.','保存済みの主線を読み込めません。元のデータは変更せず、練習は続けられます。','Der gespeicherte Lernpfad ist nicht lesbar. Die Originaldaten bleiben erhalten; du kannst weiterüben.'),unavailable:L('未能打开功能，请稍后重试或从导航进入。','Could not open this feature. Retry or use navigation.','機能を開けません。再試行するかメニューから開いてください。','Die Funktion konnte nicht geöffnet werden. Versuche es erneut oder nutze die Navigation.'),opening:L('正在打开…','Opening…','開いています…','Wird geöffnet…'),reduced:L('已减少动态效果','Motion reduced','動きを減らしています','Bewegung reduziert')
  };
  const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function initial(){return {schema:VERSION,currentStepId:IDS[0],phase:'watch',reviewedStepIds:[],skippedStepIds:[],reduceMotion:false};}
  function validate(value){
    if(!value||typeof value!=='object'||Array.isArray(value)||value.schema!==VERSION||!IDS.includes(value.currentStepId)||!PHASES.includes(value.phase)||typeof value.reduceMotion!=='boolean')throw Error('Invalid learning journey');
    for(const key of ['reviewedStepIds','skippedStepIds'])if(!Array.isArray(value[key])||value[key].length>6||value[key].some(id=>!IDS.includes(id))||new Set(value[key]).size!==value[key].length)throw Error('Invalid journey progress');
    if(value.reviewedStepIds.some(id=>value.skippedStepIds.includes(id)))throw Error('Conflicting journey status');
    return {schema:VERSION,currentStepId:value.currentStepId,phase:value.phase,reviewedStepIds:IDS.filter(id=>value.reviewedStepIds.includes(id)),skippedStepIds:IDS.filter(id=>value.skippedStepIds.includes(id)),reduceMotion:value.reduceMotion};
  }
  function createJourney(options={}){
    const env=options.environment||root;let storage=null;try{storage=Object.prototype.hasOwnProperty.call(options,'storage')?options.storage:env.localStorage;}catch{}
    const storageKey=options.storageKey||STORAGE_KEY;if(typeof storageKey!=='string'||!/^smartvio-learning-journey-v1(?::[A-Za-z0-9_%.-]{1,256})?$/.test(storageKey))throw Error('Invalid journey storage key');
    let record=initial(),host=null,settings={},lang='zh',paused=false,hidden=false,systemReduced=false,mq=null,restoreFailed=false,storageFailed=false,disposed=false,navigating=false,generation=0,replay=0,notice='';
    try{const raw=storage?.getItem(storageKey);if(raw!==null&&raw!==undefined){if(typeof raw!=='string'||raw.length>8192)throw Error('Invalid journey storage');record=validate(JSON.parse(raw));}}catch{restoreFailed=true;}
    const item=()=>STEPS.find(s=>s.id===record.currentStepId),word=(key,args={})=>{let t=WORDS[key]?.[lang]||WORDS[key]?.en||key;for(const [k,v]of Object.entries(args))t=t.replace('{'+k+'}',String(v));return t;},motion=()=>record.reduceMotion||systemReduced?'reduced':paused||hidden?'paused':'playing';
    function callback(name,...args){try{const r=(settings[name]||options[name])?.(...args);r?.catch?.(()=>{});}catch{}}
    function publish(next){record=validate(next);let persisted=false;if(!restoreFailed)try{if(!storage?.setItem)throw Error('Storage unavailable');storage.setItem(storageKey,JSON.stringify(record));persisted=true;storageFailed=false;}catch{storageFailed=true;}notice=restoreFailed?'corrupt':persisted?'saved':'volatile';callback('onChange',clone(record),{persisted});return persisted;}
    function syncMotion(){const scene=host?.querySelector?.('[data-lj-scene]');scene?.setAttribute?.('data-motion',motion());const button=host?.querySelector?.('[data-lj-action="motion"]');if(button){button.disabled=motion()==='reduced';button.setAttribute?.('aria-pressed',String(paused));button.textContent=word(paused?'play':'pause');}}
    function illustration(step){const kind=settings.instrumentType==='acoustic'?'acoustic':'electric';const art=env.SVViolinArt||root.SVViolinArt;if(typeof art?.teaching==='function')return art.teaching({step:step.id,instrumentType:kind,lang});let overlay='';
      if(step.id==='hold'||step.id==='open')overlay='<g class="lj-bow"><path d="M48 169L274 157" stroke="#8e673b" stroke-width="4" stroke-linecap="round"/><path d="M48 175L274 163" stroke="#e2cfaa" stroke-width="2"/><rect x="49" y="165" width="18" height="14" rx="3" fill="#34332e"/></g>';
      if(step.id==='fingers')overlay='<g class="lj-finger"><circle cx="160" cy="86" r="16" fill="#cf4938"/><text x="160" y="92" text-anchor="middle" fill="#fff" font-size="17">1</text></g>';
      if(step.id==='tune')overlay=['G','D','A','E'].map((s,i)=>'<g><circle cx="'+(82+i*52)+'" cy="219" r="19" fill="#faf7ef" stroke="#c9a66d"/><text x="'+(82+i*52)+'" y="225" text-anchor="middle" fill="#3a3932" font-size="17">'+s+'</text></g>').join('');
      if(step.id==='open')overlay+=[1,2,3,4].map((s,i)=>'<g class="lj-beat" style="--lj-beat:'+i+'"><circle cx="'+(82+i*52)+'" cy="219" r="15" fill="#ead4b0"/><text x="'+(82+i*52)+'" y="225" text-anchor="middle" fill="#3a3932" font-size="16">'+s+'</text></g>').join('');
      if(step.id==='melody')overlay='<g fill="#cf4938"><path d="M243 45v30h3V45Z M279 54v30h3V54Z"/><ellipse cx="238" cy="75" rx="8" ry="5"/><ellipse cx="274" cy="84" rx="8" ry="5"/></g>';
      return '<img class="lj-violin" src="visuals/violin-'+kind+'-v27.svg" alt="" width="320" height="250"><svg class="lj-overlay" viewBox="0 0 320 250" aria-hidden="true" focusable="false">'+overlay+'</svg>';
    }
    function render(focus){if(!host||disposed)return;const step=item(),index=IDS.indexOf(step.id),complete=record.reviewedStepIds.includes(step.id),storageNotice=notice==='unavailable'?notice:restoreFailed?'corrupt':storageFailed||!storage?'volatile':notice;
      const nextAction=record.phase==='watch'?'watch-next':record.phase==='try'?'try-next':'review-next';
      host.innerHTML='<section class="lj-journey" data-i18n-ignore data-no-i18n lang="'+lang+'" aria-label="'+E(word('title'))+'"><header class="lj-header"><div><h2>'+E(word('title'))+'</h2><p>'+E(word('intro'))+'</p><div class="lj-progress" role="progressbar" aria-label="'+E(word('count',{n:record.reviewedStepIds.length}))+'" aria-valuemin="0" aria-valuemax="6" aria-valuenow="'+record.reviewedStepIds.length+'"><span style="width:'+record.reviewedStepIds.length/6*100+'%"></span></div></div><span class="lj-count">'+E(word('count',{n:record.reviewedStepIds.length}))+'</span></header>'+(record.reviewedStepIds.length===6?'<p class="lj-complete" role="status">'+E(word('allDone'))+'</p>':'')+'<div class="lj-layout"><nav class="lj-steps" aria-label="'+E(word('title'))+'">'+STEPS.map((s,i)=>'<button type="button" class="lj-step" data-lj-step="'+s.id+'"'+(s.id===step.id?' aria-current="step"':'')+'><span class="lj-step-number">'+(i+1)+'</span><span class="lj-step-title">'+E(s.title[lang])+'</span><small class="lj-step-state">'+E(word(s.id===step.id?'current':record.reviewedStepIds.includes(s.id)?'reviewed':record.skippedStepIds.includes(s.id)?'skipped':'pending'))+'</small></button>').join('')+'</nav><article class="lj-current"><header><span class="lj-kicker">'+E(word('step',{n:index+1}))+'</span><h3 data-lj-heading tabindex="-1">'+E(step.title[lang])+'</h3><p class="lj-goal">'+E(step.goal[lang])+'</p></header><div class="lj-phase-tabs" role="tablist" aria-label="'+E(step.title[lang])+'">'+PHASES.map(p=>'<button type="button" role="tab" id="lj-tab-'+p+'" data-lj-phase="'+p+'" aria-controls="lj-phase-panel" aria-selected="'+(record.phase===p)+'" tabindex="'+(record.phase===p?'0':'-1')+'">'+E(word(p))+'</button>').join('')+'</div><div id="lj-phase-panel" class="lj-phase-panel" role="tabpanel" aria-labelledby="lj-tab-'+record.phase+'"><figure class="lj-figure"><div class="lj-scene" data-lj-scene data-motion="'+motion()+'" data-replay="'+replay+'">'+illustration(step)+'</div><figcaption>'+E(word('illustration'))+'</figcaption><div class="lj-motion-controls"><button type="button" data-lj-action="motion" aria-pressed="'+paused+'"'+(motion()==='reduced'?' disabled':'')+'>'+E(word(paused?'play':'pause'))+'</button><button type="button" data-lj-action="replay">'+E(word('replay'))+'</button><button type="button" data-lj-action="reduce" aria-pressed="'+record.reduceMotion+'">'+E(word('reduce'))+'</button></div>'+(motion()==='reduced'?'<p class="lj-motion-note">'+E(word('reduced'))+'</p>':'')+'</figure><div class="lj-instructions">'+(record.phase==='review'?'<p>'+E(word('reflection'))+'</p>':'<ol>'+step.instructions.map(t=>'<li>'+E(t[lang])+'</li>').join('')+'</ol>')+'</div><div class="lj-actions">'+(record.phase==='try'?'<button type="button" class="lj-primary" data-lj-action="open"'+(navigating?' disabled':'')+'>'+E(navigating?word('opening'):step.entryLabel[lang])+' ↗</button>':'')+'<button type="button" class="'+(record.phase==='try'?'lj-secondary':'lj-primary')+'" data-lj-action="'+nextAction+'">'+E(word(record.phase==='watch'?'watchNext':record.phase==='try'?'tryNext':index<5?'finish':'finished'))+'</button>'+(record.phase==='review'&&index>2?'<button type="button" class="lj-secondary" data-lj-action="record"'+(navigating?' disabled':'')+'>'+E(word('record'))+'</button>':'')+(record.phase==='review'&&complete?'<button type="button" class="lj-secondary" data-lj-action="undo">'+E(word('undo'))+'</button>':'')+'</div></div><p class="lj-progress-note">'+E(word('progressNote'))+'</p></article></div><footer class="lj-footer"><button type="button" data-lj-action="previous"'+(index===0?' disabled':'')+'>'+E(word('previous'))+'</button><button type="button" data-lj-action="skip">'+E(word('skip'))+'</button></footer><p class="lj-status" role="status" aria-live="polite">'+E(storageNotice?word(storageNotice):'')+'</p></section>';
      if(focus==='heading')host.querySelector?.('[data-lj-heading]')?.focus?.({preventScroll:true});else if(focus?.startsWith('phase:'))host.querySelector?.('[data-lj-phase="'+focus.slice(6)+'"]')?.focus?.({preventScroll:true});else if(focus)host.querySelector?.('[data-lj-action="'+focus+'"]')?.focus?.({preventScroll:true});
    }
    function setStep(id){if(disposed)throw Error('Journey disposed');if(!IDS.includes(id))throw Error('Unknown journey step');if(id!==record.currentStepId){generation++;navigating=false;publish({...record,currentStepId:id,phase:'watch'});paused=false;}render('heading');return clone(record);}
    function setPhase(phase){if(disposed)throw Error('Journey disposed');if(!PHASES.includes(phase))throw Error('Unknown journey phase');generation++;navigating=false;publish({...record,phase});render('phase:'+phase);return clone(record);}
    async function navigate(recording=false){if(navigating||disposed||!host)return;const step=item(),entry=recording?{page:'studio',target:'[data-action="record-audio"]'}:step.entry,at=++generation;navigating=true;render();try{const guard=settings.beforeNavigate||options.beforeNavigate;if(typeof guard==='function'&&await guard(step.id)===false)return;if(!host||disposed||at!==generation)return;const handler=settings.onNavigate||options.onNavigate;if(typeof handler==='function')await handler(entry.page,{stepId:step.id,returnTo:'learn',...(entry.lessonId?{lessonId:entry.lessonId}:{}),...(entry.target?{target:entry.target}:{})});else if(env.location)env.location.hash='#'+entry.page;else throw Error('No navigation handler');}catch{if(!disposed&&host&&at===generation){notice='unavailable';callback('onNotice',word('unavailable'));}}finally{if(at===generation){navigating=false;render('open');}}}
    function click(event){const target=event.target.closest?.('[data-lj-action],[data-lj-step],[data-lj-phase]');if(!target||target.disabled||!host?.contains?.(target))return;event.preventDefault?.();if(target.dataset.ljStep){setStep(target.dataset.ljStep);return;}if(target.dataset.ljPhase){setPhase(target.dataset.ljPhase);return;}const action=target.dataset.ljAction,index=IDS.indexOf(record.currentStepId);
      if(action==='previous'&&index>0)setStep(IDS[index-1]);else if(action==='watch-next')setPhase('try');else if(action==='try-next')setPhase('review');else if(action==='review-next'){const id=record.currentStepId;publish({...record,reviewedStepIds:IDS.filter(s=>s===id||record.reviewedStepIds.includes(s)),skippedStepIds:record.skippedStepIds.filter(s=>s!==id),currentStepId:IDS[Math.min(5,index+1)],phase:index<5?'watch':'review'});render('heading');}
      else if(action==='skip'){const id=record.currentStepId;publish({...record,skippedStepIds:record.reviewedStepIds.includes(id)?record.skippedStepIds:IDS.filter(s=>s===id||record.skippedStepIds.includes(s)),currentStepId:IDS[Math.min(5,index+1)],phase:'watch'});render('heading');}
      else if(action==='undo'){publish({...record,reviewedStepIds:record.reviewedStepIds.filter(s=>s!==record.currentStepId)});render();}else if(action==='open')void navigate();else if(action==='record')void navigate(true);else if(action==='motion'&&motion()!=='reduced'){paused=!paused;syncMotion();}else if(action==='replay'){paused=false;replay++;render('replay');}else if(action==='reduce'){publish({...record,reduceMotion:!record.reduceMotion});render('reduce');}
    }
    function keydown(event){const target=event.target.closest?.('[data-lj-phase]');if(!target||!host?.contains?.(target))return;const index=PHASES.indexOf(target.dataset.ljPhase),delta=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:0;if(delta){event.preventDefault?.();setPhase(PHASES[(index+delta+3)%3]);}else if(event.key==='Home'||event.key==='End'){event.preventDefault?.();setPhase(PHASES[event.key==='Home'?0:2]);}}
    function visibility(){hidden=!!env.document?.hidden;syncMotion();}function mediaChanged(e){systemReduced=!!e.matches;render();}
    function unmount(){generation++;navigating=false;if(host){host.querySelector?.('[data-lj-scene]')?.setAttribute?.('data-motion','paused');host.removeEventListener('click',click);host.removeEventListener('keydown',keydown);host=null;}env.document?.removeEventListener?.('visibilitychange',visibility);if(mq?.removeEventListener)mq.removeEventListener('change',mediaChanged);else mq?.removeListener?.(mediaChanged);mq=null;}
    function mount(element,mountOptions={}){if(disposed)throw Error('Journey disposed');unmount();if(typeof element==='string')element=env.document?.querySelector?.(element);if(!element?.addEventListener)throw Error('Journey host required');host=element;settings=mountOptions;lang=LANGUAGES.includes(settings.lang)?settings.lang:'zh';hidden=!!env.document?.hidden;try{mq=env.matchMedia?.('(prefers-reduced-motion: reduce)')||null;systemReduced=!!mq?.matches;}catch{mq=null;systemReduced=false;}host.addEventListener('click',click);host.addEventListener('keydown',keydown);env.document?.addEventListener?.('visibilitychange',visibility);if(mq?.addEventListener)mq.addEventListener('change',mediaChanged);else mq?.addListener?.(mediaChanged);render();return api;}
    function clear(){if(disposed)return {cleared:false,committed:false};try{if(!storage?.removeItem)throw Error('Storage unavailable');storage.removeItem(storageKey);generation++;navigating=false;record=initial();restoreFailed=false;storageFailed=false;paused=false;notice='';render();return {cleared:true,committed:true};}catch{storageFailed=true;render();return {cleared:false,committed:false};}}
    const api={mount,unmount,render,setStep,setPhase,state:()=>clone(record),exportState:()=>clone(record),status:()=>({mounted:!!host,disposed,restoreFailed,storageFailed,navigating,motion:motion(),persistedAvailable:!!storage&&!restoreFailed&&!storageFailed}),clear,setLanguage(value){if(!LANGUAGES.includes(value))throw Error('Unsupported journey language');lang=value;render();},dispose(){unmount();disposed=true;}};return api;
  }
  return Object.freeze({VERSION,STORAGE_KEY,steps:()=>clone(STEPS),validate,createJourney});
});
